  "Auto": "Авто",
  "Auto (32)": "Авто (32)",
  "Auto (Default)": "Авто (по умолчанию)",
  "Auto (by genome size)": "Авто (по размеру генома)",
  "Auto ({count} parallel run)": "Авто ({count} параллельный запуск)",
  "Auto ({count} parallel runs)": {"one": "Авто ({count} параллельный запуск)", "few": "Авто ({count} параллельных запуска)", "many": "Авто ({count} параллельных запусков)", "other": "Авто ({count} параллельного запуска)"},
  "Auto ({count})": "Авто ({count})",
  "Auto ({mode})": "Авто ({mode})",
