  "Auto Reflow": "Автоперераспределение",
  "Auto Reflow failed. Current diagram is kept.": "Не удалось выполнить автоперераспределение. Текущая диаграмма сохранена.",
  "Auto embeds labels that fit and routes the rest externally. Embedded Only drops labels that need external placement. External Only keeps labels outside feature bodies.": "Если выбрано Авто, подписи, которые помещаются, встраиваются в элемент, а остальные выносятся наружу. Если выбрано Только встроенные, подписи, которым нужно внешнее размещение, отбрасываются. Если выбрано Только внешние, подписи остаются снаружи элементов.",
  "Auto follows the track layout (Above or Features on axis: labels above; Below: labels below). Above Feature draws labels above features (and below negative-strand features when Separate Strands is on).": "Если выбрано Авто, размещение определяется макетом треков (Выше или Элементы на оси — подписи выше; Ниже — подписи ниже). Если выбрано Над элементом, подписи рисуются над элементами (и под элементами на обратной цепи, когда включен параметр Разделять по цепям).",
  "Auto hides these fields throughout the diagram": "если выбрано Авто, эти поля скрываются на всей диаграмме",
  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "Если выбрано Авто, CDS с общим идентификатором локуса образуют одну единицу, а каждая из остальных CDS — отдельную единицу. Если выбрано CDS, каждая CDS — единица. Если выбрано Локус, каждый локус — единица; для этого у каждой CDS нужен идентификатор локуса, например /locus_tag.",
  "Auto runs threaded LOSAT when this browser supports it, and serial LOSAT otherwise. LOSATN task dc-megablast needs threaded LOSAT.": "Если выбрано Авто, используется многопоточный LOSAT, когда его поддерживает этот браузер, а иначе последовательный LOSAT. Для задачи LOSATN dc-megablast нужен многопоточный LOSAT.",
  "Auto shows these fields throughout the diagram": "если выбрано Авто, эти поля показываются на всей диаграмме",
  "Auto will hide these fields throughout the diagram on the next successful Generate": "если выбрано Авто, эти поля будут скрыты на всей диаграмме при следующем успешном построении",
  "Auto will show these fields throughout the diagram on the next successful Generate": "если выбрано Авто, эти поля будут показаны на всей диаграмме при следующем успешном построении",
