  "Bakta also sets the CDS default color to #cccccc and the Legend box size and font size to 12.": "Для Bakta также задаются цвет CDS по умолчанию #cccccc и значение 12 для размера образца цвета и размера шрифта легенды.",
  "Band (annotation lane)": "Полоса (дорожка аннотаций)",
  "Bar (Simple)": "Отрезок (простой)",
  "Base colors for features, comparison tracks, and collinear blocks. The selected palette supplies unchanged colors; colors you edit override it; when you change the palette, a dialog asks whether to keep them.": "Базовые цвета элементов, треков сравнения и коллинеарных блоков. Выбранная палитра задает неизмененные цвета; измененные вами цвета переопределяют ее; при смене палитры диалоговое окно спросит, оставить ли их.",
  "Base text shown in the diagram legend. Leave blank to use the auto label shown here; two-color tracks add (+) and (-).": "Основной текст, показываемый в легенде диаграммы. Оставьте пустым, чтобы использовать автоматическую подпись, показанную здесь; для двухцветных треков добавляются (+) и (-).",
