  "Browser-oriented SVG with embedded controls. Rich Feature Popup controls how much feature detail is embedded.": "SVG для браузера со встроенными элементами управления. Параметр Расширенное всплывающее окно элемента определяет, сколько сведений об элементе встраивается.",
