  "Changes this legend swatch only. The plot keeps the color set in Settings.": "Изменяет только этот образец цвета в легенде. График сохраняет цвет, заданный в настройках.",
  "Change…": "Изменить…",
  "Changing \"{setting}\" to \"{value}\" removes the lane for {count} feature you placed manually.": "Изменение параметра «{setting}» на значение «{value}» убирает дорожку для {count} элемента, размещенного вами вручную.",
  "Changing \"{setting}\" to \"{value}\" removes the lane for {count} features you placed manually.": {"one": "Изменение параметра «{setting}» на значение «{value}» убирает дорожки для {count} элемента, размещенного вами вручную.", "few": "Изменение параметра «{setting}» на значение «{value}» убирает дорожки для {count} элементов, размещенных вами вручную.", "many": "Изменение параметра «{setting}» на значение «{value}» убирает дорожки для {count} элементов, размещенных вами вручную.", "other": "Изменение параметра «{setting}» на значение «{value}» убирает дорожки для {count} элемента, размещенного вами вручную."},
  "Check the Python group syntax.": "Проверьте синтаксис групп Python.",
  "Check the character range.": "Проверьте диапазон символов.",
  "Check the comparison inputs and display transforms.": "Проверьте входные данные сравнения и преобразования отображения.",
  "Check the comparison inputs: a comparison link does not identify the feature at one of its ends.": "Проверьте входные данные сравнения: связь сравнения не определяет элемент на одном из своих концов.",
  "Check the escape sequence.": "Проверьте escape-последовательность.",
