  "Checking color rule…": "Проверка правила цвета…",
  "Choose BLAST TSV for {name}": "Выбрать BLAST TSV для пары {name}",
  "Choose LOSATN or TLOSATX for comparison rings.": "Выберите LOSATN или TLOSATX для колец сравнения.",
  "Choose On to show it.": "Выберите значение Вкл., чтобы показать подпись.",
  "Choose Run LOSAT or Upload BLAST TSV to configure comparisons.": "Выберите вариант Запустить LOSAT или Загрузить BLAST TSV, чтобы настроить сравнения.",
