  "Choose a fix": "Выбрать исправление",
  "Choose a gbdraw Session file.": "Выберите файл сеанса gbdraw.",
  "Choose a gene": "Выбор гена",
  "Choose a nucleotide, protein, or translated nucleotide search. LOSATP settings are preserved while another mode is active.": "Выберите поиск по нуклеотидным последовательностям, поиск белков или поиск по транслированным нуклеотидным последовательностям. Настройки LOSATP сохраняются, пока активен другой режим.",
  "Choose a readable TrueType or OpenType font file (.ttf, .otf, .ttc, .otc) that names its font family.": "Выберите доступный для чтения файл шрифта TrueType или OpenType (.ttf, .otf, .ttc, .otc), в котором указано семейство шрифтов.",
