  "Choose each feature type's rendering. Underlay removes it from feature lanes and labels, then highlights each feature's span across the full thickness of the feature track, behind foreground features.": "Выберите отрисовку для каждого типа элемента. Если выбрано Подложка, тип убирается из дорожек элементов и подписей, а диапазон каждого элемента выделяется на всю толщину трека элементов позади элементов переднего плана.",
