  "Choose record pairs that the LOSAT search can run: two or more records, LOSAT rows only with a LOSAT program, and LOSATP Pairwise for selected pairs.": "Выберите пары записей, для которых можно выполнить поиск LOSAT: две или более записи, строки LOSAT только с программой LOSAT и режим LOSATP «Попарные совпадения» для выбранных пар.",
