  "Choose the placement Overlay anchor (Circular) or On axis (Linear) when an anchor or an Extend to slot is selected.": "Выберите размещение Наложение на якорь (круговая диаграмма) или На оси (линейная диаграмма), когда выбран якорь или слот в поле «Продлить до».",
