  "Choosing \"{setting}\" removes the lane for {count} features you placed manually.": {"one": "Команда «{setting}» убирает дорожки для {count} элемента, размещенного вами вручную.", "few": "Команда «{setting}» убирает дорожки для {count} элементов, размещенных вами вручную.", "many": "Команда «{setting}» убирает дорожки для {count} элементов, размещенных вами вручную.", "other": "Команда «{setting}» убирает дорожки для {count} элемента, размещенного вами вручную."},
  "Choosing a file here switches the plan to Selected pairs; pairs without a file are then not compared.": "При выборе файла здесь план переключается на вариант Выбранные пары; пары без файла при этом не сравниваются.",
