  "Collision-avoidance row for Line, Bracket, and Band. Leave blank for Auto; use 0 for the first row, 1 for the second, and so on. Highlight always covers the full feature band.": "Строка для размещения меток Линия, Скобка и Полоса без перекрытий. Оставьте пустым для автоматического значения; 0 — первая строка, 1 — вторая и так далее. Метка Выделение всегда охватывает всю полосу элементов.",
  "Color": "Цвет",
  "Color Change Scope": "Охват изменения цвета",
  "Color features whose qualifier value matches a regular expression, case-insensitive (for example NADH). Choose a suggested qualifier or type any qualifier name. When rules use the same qualifier, the first matching row wins; Move rule up and down changes that order. Rules on different qualifiers are tried in the order the qualifiers appear on the feature.": "Окрашивает элементы, значение квалификатора которых соответствует регулярному выражению без учета регистра (например, NADH). Выберите предложенный квалификатор или введите любое имя квалификатора. Если правила используют один и тот же квалификатор, срабатывает первая подходящая строка; порядок меняют кнопки Переместить правило вверх и Переместить правило вниз. Правила для разных квалификаторов проверяются в том порядке, в котором квалификаторы идут у элемента.",
