  "Custom Track Slots no longer read this field. Use slot-level radius, width, inner_gap_px, outer_gap_px, side, and z fields.": "Пользовательские слоты треков больше не читают это поле. Используйте поля слота radius, width, inner_gap_px, outer_gap_px, side и z.",
  "Custom position": "Пользовательское положение",
  "Custom stack Depth rows control rendering. Disable the custom stack to change this simple control.": "Отрисовкой управляют строки глубины пользовательского стека. Отключите пользовательский стек, чтобы изменить этот простой элемент управления.",
  "Custom stack geometry is active. Use each Depth row width, or Reset to copy this value into the stack.": "Действует геометрия пользовательского стека. Используйте ширину каждой строки глубины или нажмите кнопку Сбросить, чтобы скопировать это значение в стек.",
  "Custom stack geometry is active. Use the Dinucleotide content row radius, or Reset to copy this value into the stack.": "Действует геометрия пользовательского стека. Используйте радиус строки Состав динуклеотидов или нажмите кнопку Сбросить, чтобы скопировать это значение в стек.",
  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "Действует геометрия пользовательского стека. Используйте ширину строки Состав динуклеотидов или нажмите кнопку Сбросить, чтобы скопировать это значение в стек.",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "Действует геометрия пользовательского стека. Используйте радиус строки Skew динуклеотидов или нажмите кнопку Сбросить, чтобы скопировать это значение в стек.",
  "Custom stack geometry is active. Use the Dinucleotide skew row width, or Reset to copy this value into the stack.": "Действует геометрия пользовательского стека. Используйте ширину строки Skew динуклеотидов или нажмите кнопку Сбросить, чтобы скопировать это значение в стек.",
  "Custom stack geometry is active. Use the Features row width, or Reset to copy this value into the stack.": "Действует геометрия пользовательского стека. Используйте ширину строки Элементы или нажмите кнопку Сбросить, чтобы скопировать это значение в стек.",
  "Custom stack is saved but inactive; generation uses the simple track controls.": "Пользовательский стек сохранен, но не активен; при построении используются простые элементы управления треками.",
