  "Draw a Linear map.": "Постройте линейную диаграмму.",
  "Draw all sequences at the same displayed length. Hides the length bar.": "Рисует все последовательности одной отображаемой длины. Скрывает масштабный отрезок.",
  "Draw one circular pairwise comparison ring per uploaded BLAST outfmt 6/7 file or browser LOSATN/TLOSATX comparison sequence file (FASTA, GenBank, or DDBJ). Reverse BLAST coordinates are shown as reverse hits, not origin-spanning hits.": "Рисует одно кольцо попарного сравнения на каждый загруженный файл BLAST outfmt 6/7 или файл последовательности сравнения LOSATN/TLOSATX в браузере (FASTA, GenBank или DDBJ). Обратные координаты BLAST показываются как обратные хиты, а не как хиты, проходящие через начало последовательности.",
  "Draw records": "Отрисовать записи",
  "Draw this record": "Рисовать эту запись",
  "Draws each label that the label priority names from the gene qualifier in italics, also after its text is edited. Other labels stay upright.": "Рисует курсивом каждую подпись, текст которой берется из квалификатора gene согласно приоритету подписей, в том числе после правки этого текста. Остальные подписи рисуются прямым шрифтом.",
  "Duplicate": "Дублировать",
