  "Edit the explicit circular stack. Opening or closing this panel does not enable or alter the stack. Rows above Axis render outside and rows below Axis render inside.": "Позволяет изменить явный стек треков круговой диаграммы. Открытие и закрытие этой панели не включает и не изменяет стек. Строки выше строки Ось рисуются снаружи, строки ниже — внутри.",
  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "Позволяет изменить явный стек треков линейной диаграммы. Открытие и закрытие этой панели не включает и не изменяет стек. Стрелки меняют порядок в пределах текущей стороны; команды меню Действия со строкой перемещают строки через границу.",
  "Edit this record in its File card in the sidebar.": "Измените эту запись в ее карточке файла на боковой панели.",
