  "Files cannot be moved while Record Layout does not give each File its own consecutive rows. Change the rows in Advanced comparison and layout → Record Layout.": "Файлы нельзя перемещать, пока в разделе Макет записей каждому файлу не выделены собственные строки, идущие подряд. Измените строки в разделе Дополнительно: сравнение и макет → Макет записей.",
