  "Fix before Generate": "Исправить перед построением",
  "Fix the identity colour scale so figures with different thresholds share colours and Legend labels. Leave the minimum blank to colour from the minimum identity to 100%.": "Зафиксируйте цветовую шкалу идентичности, чтобы диаграммы с разными порогами имели одинаковые цвета и подписи в легенде. Оставьте минимум пустым, чтобы раскрашивать от минимальной идентичности до 100%.",
  "Font": "Шрифт",
  "Font size": "Размер шрифта",
  "Font size for GC content percent tick labels. Leave blank for auto.": "Размер шрифта подписей делений процентов GC-состава. Оставьте пустым для автоматического значения.",
  "Font size for circular tick labels. Leave blank to use the default size.": "Размер шрифта подписей делений круговой диаграммы. Оставьте пустым, чтобы использовать размер по умолчанию.",
  "Font size for feature labels.": "Размер шрифта подписей элементов.",
  "Font size for record-label text (species/strain in circular; organism/replicon/accession/length stack in linear).": "Размер шрифта текста подписи записи (в круговой диаграмме — вид/штамм; в линейной — блок организм/репликон/номер доступа/длина).",
  "Font size for ruler tick labels, including rulers drawn on record axes.": "Размер шрифта подписей делений линейки, в том числе линеек на осях записей.",
  "Font size for the circular shared plot title. Only used when the title position is Top or Bottom.": "Размер шрифта общего заголовка круговой диаграммы. Используется, только когда положение заголовка — Сверху или Снизу.",
  "Font size for the legend text.": "Размер шрифта текста легенды.",
  "Font size for the linear plot title.": "Размер шрифта заголовка линейной диаграммы.",
  "Font size for the simple bar scale label.": "Размер шрифта подписи простого масштабного отрезка.",
  "Font size for this track's depth tick labels. Leave blank for auto.": "Размер шрифта подписей делений глубины для этого трека. Оставьте пустым для автоматического значения.",
  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "Не удалось подготовить шрифт {family} для PDF. Текст отрисован шрифтом {substitute}.",
  "Font {family} is not embedded in the PDF: its license (OS/2 fsType) does not allow embedding. Its text is drawn in {substitute}.": "Шрифт {family} не встроен в PDF: его лицензия (OS/2 fsType) не разрешает встраивание. Текст отрисован шрифтом {substitute}.",
  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "Шрифт {family} не встроен: его лицензия (OS/2 fsType) не разрешает встраивание. В SVG текст отображается этим шрифтом только там, где установлен шрифт {family}.",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "Шрифты, загруженные на этой странице, не удалось снова подготовить для отрисовки. Загрузите их заново в разделе Шрифт или выберите другой шрифт.",
  "For Extend to, select an eligible enabled slot other than the anchor, or None.": "В поле «Продлить до» выберите подходящий включенный слот, отличный от якоря, или вариант Нет.",
