  "Group paths": "Пути группы",
  "Halo": "Ореол",
  "Halo draws a white outline around the letters of each label with a leader, so leaders behind them are cut away. Box draws a white box behind the letters. None draws neither.": "Если выбрано Ореол, вокруг букв каждой подписи с линией-выноской рисуется белый контур, скрывающий участки линий-выносок позади букв. Если выбрано Рамка, за буквами рисуется белый прямоугольник. Если выбрано Нет, не рисуется ни контур, ни прямоугольник.",
  "Hatch": "Штриховка",
  "Head Length Ratio": "Отношение длины наконечника",
  "Head length and shaft width apply to Arrow features and remain available even when no feature currently uses that rendering.": "Длина наконечника и ширина тела относятся к элементам с отрисовкой Стрелка и остаются доступными, даже если ни один элемент сейчас не использует эту отрисовку.",
  "Head length divided by the full rendered feature thickness. Leave blank for Auto. Auto starts from the mode-specific default and lengthens the head as the shaft narrows.": "Длина наконечника, деленная на полную отрисованную толщину элемента. Оставьте пустым для автоматического значения. Если выбрано Авто, берется значение по умолчанию для режима, и наконечник удлиняется по мере сужения тела.",
  "Height": "Высота",
  "Height must be a positive number of pixels (px optional).": "Высота должна быть положительным числом пикселей (px, необязательно).",
  "Height of the feature blocks.": "Высота блоков элементов.",
  "Height of the linear GC content and GC skew tracks. Applies to whichever of those tracks are enabled when the diagram is generated.": "Высота треков GC-состава и GC skew на линейной диаграмме. Применяется к тем из этих треков, которые включены при построении диаграммы.",
  "Height of this linear depth coverage track in px. Leave blank for auto.": "Высота этого трека глубины покрытия на линейной диаграмме в px. Оставьте пустым для автоматического значения.",
