  "Highlights render automatically behind the feature track. Line, Bracket, and Band render in a separate annotation lane. Custom Track Slots can override this automatic placement.": "Выделения автоматически отрисовываются позади трека элементов. Метки Линия, Скобка и Полоса отрисовываются на отдельной дорожке аннотаций. Пользовательские слоты треков могут переопределить это автоматическое размещение.",
  "Horizontal": "Горизонтально",
  "Horizontal keeps external labels level; Radial aligns them with the circle radius.": "Если выбрано Горизонтально, внешние подписи остаются горизонтальными; если выбрано Радиально, они выравниваются по радиусу окружности.",
