  "Identity scale min (%)": "Шкала идентичности, мин. (%)",
  "If you save a .gbdraw-session.json.gz and load it back in the web app, the uploaded inputs, results, and LOSAT cache are restored from the compressed JSON; these TSV files do not need to be saved separately for session restore.": "Если сохранить файл .gbdraw-session.json.gz и загрузить его обратно в веб-приложении, загруженные входные файлы, результаты и кэш LOSAT восстанавливаются из сжатого JSON; сохранять эти файлы TSV отдельно для восстановления сеанса не нужно.",
  "If you use gbdraw in your research, please cite the preprint:": "Если вы используете gbdraw в своем исследовании, процитируйте препринт:",
  "Ignored annotation table columns: {columns}. These columns are not saved in Sessions or TSV re-export.": "Игнорируемые столбцы таблицы аннотаций: {columns}. Эти столбцы не сохраняются в сеансах и не попадают в повторный экспорт TSV.",
