  "Import or add a Region annotation set in Region Annotations first": "Сначала импортируйте или добавьте набор аннотаций областей в разделе Аннотации областей",
  "Import specific color rules": "Импортировать индивидуальные правила цвета",
  "Importing it removes all {count} annotation set.": "Импорт убирает {count} набор аннотаций.",
  "Importing it removes all {count} annotation sets.": {"one": "Импорт убирает все наборы аннотаций: {count}.", "few": "Импорт убирает все наборы аннотаций: {count}.", "many": "Импорт убирает все наборы аннотаций: {count}.", "other": "Импорт убирает все наборы аннотаций: {count}."},
  "In one record, this selector names features that start at different bases. Use a selector that names one feature, such as locus_tag=<tag>.": "В одной записи этот селектор указывает на элементы, которые начинаются в разных положениях. Используйте селектор, который указывает на один элемент, например locus_tag=<tag>.",
