  "Legend: entries {items} had a color the app does not accept and were dropped.": {"one": "Легенда: пункты {items} имели цвет, который приложение не принимает, и отброшены.", "few": "Легенда: пункты {items} имели цвет, который приложение не принимает, и отброшены.", "many": "Легенда: пункты {items} имели цвет, который приложение не принимает, и отброшены.", "other": "Легенда: пункты {items} имели цвет, который приложение не принимает, и отброшены."},
  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": {"one": "Легенда: пункты {items} повторяют более ранний пункт списка и отброшены.", "few": "Легенда: пункты {items} повторяют более ранний пункт списка и отброшены.", "many": "Легенда: пункты {items} повторяют более ранний пункт списка и отброшены.", "other": "Легенда: пункты {items} повторяют более ранний пункт списка и отброшены."},
  "Legend: entry {items} had a color the app does not accept and was dropped.": "Легенда: пункт {items} имел цвет, который приложение не принимает, и отброшен.",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "Легенда: пункт {items} повторяет более ранний пункт списка и отброшен.",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Легенда: правка цвета, сохраненная под именем «{label}» ({path}), переносится на строку «{used}», у которой уже есть своя правка; используется правка этой строки, а переносимая правка отброшена.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Легенда: правка цвета, сохраненная под именем «{label}» ({path}), задает строку «{used}», которую задает и более поздняя правка; используется поздняя правка, а эта отброшена.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "Легенда: пункт, сохраненный под именем «{label}» ({path}), переносится на строку «{used}», у которой уже есть свой пункт; используется пункт этой строки, а переносимый пункт отброшен.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Легенда: пункт, сохраненный под именем «{label}» ({path}), задает строку «{used}», которую задает и более поздняя правка; используется поздняя правка, а этот пункт отброшен.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "Легенда: положение «{stored}» ({path}) недоступно в соответствующем режиме диаграммы; оно не используется.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "Легенда: положение «{stored}» ({path}) недоступно в соответствующем режиме диаграммы; используется положение {used}.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "Легенда: правка обводки, сохраненная под именем «{label}» ({path}), переносится на строку «{used}», у которой уже есть своя правка; используется правка этой строки, а переносимая правка отброшена.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "Легенда: правка обводки, сохраненная под именем «{label}» ({path}), задает строку «{used}», которую задает и более поздняя правка; используется поздняя правка, а эта отброшена.",
