  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "Вертикальное расстояние после трека на линейной диаграмме в пикселях (px, необязательно; неотрицательное). Оставьте пустым для автоматического значения.",
  "Link Linear scale and ruler label font sizes": "Связать размеры шрифта подписей шкалы линейной диаграммы и линейки",
  "Link Scale and Ruler Label Font Sizes": "Связать размеры шрифта подписей шкалы и линейки",
  "List all 12 standard BLAST outfmt 6 fields in the \"# Fields:\" line, or remove the line so that the first 12 columns are read in the standard order.": "Перечислите все 12 стандартных полей BLAST outfmt 6 в строке «# Fields:» или уберите эту строку, чтобы первые 12 столбцов читались в стандартном порядке.",
  "Live edit": "Правка в реальном времени",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "Применяется правка в реальном времени: обновляется геометрия. Уже примененные прямые правки сохраняются.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "Не удалось применить правку в реальном времени: уже примененные прямые правки сохранены; геометрию, возможно, еще нужно обновить.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, for Hide GC Content and Hide GC Skew turned off": "Правка в реальном времени. Показ трека применяется при построении в следующих случаях: если трек не был отрисован в результате на момент загрузки сеанса; после изменения файла глубины, серии или записей, с которыми сопоставлены файлы глубины; для строки пользовательского стека, добавленной после последнего построения, или стека, который не удалось создать при последнем построении; при использовании пользовательского стека треков круговой диаграммы либо ширины или радиусов треков круговой диаграммы — при отключении параметров Скрыть GC-состав и Скрыть GC skew",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "Правка в реальном времени: цвет элемента, текст подписи и видимость обновляют текущий результат; геометрия может перерисоваться автоматически.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "Правка в реальном времени: текст легенды, порядок, обводка и удаление обновляют текущий результат.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change": "Правка в реальном времени; положение применяется при построении после изменения параметра Холст для нескольких записей",
  "Load": "Загрузить",
