  "Raw LOSATP search limit per query protein (--max-target-seqs). In a within-record search the query protein itself counts as one target. Leave blank for an unbounded search, the default. Changing this value requires matching raw search results. Each mode remembers its own hit limits.": "Ограничение необработанного поиска LOSATP на один белок query (--max-target-seqs). В поиске внутри записи сам белок query считается одной целью. Оставьте пустым для поиска без ограничения — это значение по умолчанию. При изменении этого значения требуются соответствующие необработанные результаты поиска. Каждый режим запоминает свои ограничения числа хитов.",
