  "Reverse-complements the record when this feature is on the − strand.": "Для записи берется обратный комплемент, если этот элемент находится на цепи −.",
  "Reverses {records} so all {count} chosen features point left.": {"one": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены влево.", "few": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены влево.", "many": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены влево.", "other": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены влево."},
  "Reverses {records} so all {count} chosen features point right.": {"one": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены вправо.", "few": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены вправо.", "many": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены вправо.", "other": "Инвертирует {records}, чтобы все выбранные элементы ({count}) были направлены вправо."},
  "Reverses {records} so the chosen feature points left.": "Инвертирует {records}, чтобы выбранный элемент был направлен влево.",
