  "Search with a JavaScript regular expression; upper and lower case match alike.": "Поиск по регулярному выражению JavaScript; регистр не учитывается.",
  "Select Hide GC Content, or reduce GC Content Width (with Custom Track Slots on, the row width).": "Включите параметр Скрыть GC-состав или уменьшите значение параметра Ширина трека GC-состава (при включенных пользовательских слотах треков — ширину строки).",
  "Select Hide GC Skew, or reduce GC Skew Width (with Custom Track Slots on, the row width).": "Включите параметр Скрыть GC skew или уменьшите значение параметра Ширина трека GC skew (при включенных пользовательских слотах треков — ширину строки).",
