  "location and record_location rows cannot be matched to {count} labels on cropped, reverse-complemented, or rotated records until the diagram records where it drew them. Generate the diagram again, then load the table.": {"one": "Строки location и record_location нельзя сопоставить с {count} подписью на записях, которые кадрированы, повернуты или преобразованы в обратный комплемент, пока диаграмма не запомнит, где она их отрисовала. Постройте диаграмму заново, затем загрузите таблицу.", "few": "Строки location и record_location нельзя сопоставить с {count} подписями на записях, которые кадрированы, повернуты или преобразованы в обратный комплемент, пока диаграмма не запомнит, где она их отрисовала. Постройте диаграмму заново, затем загрузите таблицу.", "many": "Строки location и record_location нельзя сопоставить с {count} подписями на записях, которые кадрированы, повернуты или преобразованы в обратный комплемент, пока диаграмма не запомнит, где она их отрисовала. Постройте диаграмму заново, затем загрузите таблицу.", "other": "Строки location и record_location нельзя сопоставить с {count} подписи на записях, которые кадрированы, повернуты или преобразованы в обратный комплемент, пока диаграмма не запомнит, где она их отрисовала. Постройте диаграмму заново, затем загрузите таблицу."},
