  "{count} Feature visibility edit from an older Session hid every feature with the same hash, such as each copy of a duplicated record. It now applies only to the feature that was edited, so the next Generate draws the others.": "{count} правка видимости элемента из более старого сеанса скрывала все элементы с тем же хешем, например каждую копию дублированной записи. Теперь она применяется только к измененному элементу, поэтому при следующем построении остальные будут отрисованы.",
  "{count} Feature visibility edits from an older Session hid every feature with the same hash, such as each copy of a duplicated record. Each now applies only to the feature that was edited, so the next Generate draws the others.": {"one": "{count} правка видимости элемента из более старого сеанса скрывала все элементы с тем же хешем, например каждую копию дублированной записи. Теперь каждая применяется только к измененному элементу, поэтому при следующем построении остальные будут отрисованы.", "few": "{count} правки видимости элемента из более старого сеанса скрывали все элементы с тем же хешем, например каждую копию дублированной записи. Теперь каждая применяется только к измененному элементу, поэтому при следующем построении остальные будут отрисованы.", "many": "{count} правок видимости элемента из более старого сеанса скрывало все элементы с тем же хешем, например каждую копию дублированной записи. Теперь каждая применяется только к измененному элементу, поэтому при следующем построении остальные будут отрисованы.", "other": "{count} правки видимости элемента из более старого сеанса скрывало все элементы с тем же хешем, например каждую копию дублированной записи. Теперь каждая применяется только к измененному элементу, поэтому при следующем построении остальные будут отрисованы."},
  "{count} LOSAT result is cached and reused when the inputs and settings match.": "Кэшировано результатов LOSAT: {count}. Кэш используется повторно, когда входные данные и настройки совпадают.",
