  "{count} hash= value from an older Session could not be renamed to the hash of a feature in its source record: the saved diagram drew a cropped or reverse-complemented record, and the value names features of several source hashes there, or the sources were not read again. hash= now names a feature by its hash in the source record, so the value may now match another feature or none.": "Не удалось переименовать {count} значение hash= из более старого сеанса в хеш элемента в его исходной записи: сохраненная диаграмма отображала кадрированную запись или обратный комплемент записи, и значение там указывает на элементы с несколькими исходными хешами, либо источники не были прочитаны повторно. Теперь hash= указывает на элемент по его хешу в исходной записи, поэтому значение теперь может совпасть с другим элементом или не совпасть ни с одним.",
  "{count} hash= values from an older Session could not be renamed to the hash of a feature in its source record: the saved diagram drew a cropped or reverse-complemented record, and the value names features of several source hashes there, or the sources were not read again. hash= now names a feature by its hash in the source record, so each may now match another feature or none.": {"one": "Не удалось переименовать {count} значение hash= из более старого сеанса в хеш элемента в его исходной записи: сохраненная диаграмма отображала кадрированную запись или обратный комплемент записи, и значения там указывают на элементы с несколькими исходными хешами, либо источники не были прочитаны повторно. Теперь hash= указывает на элемент по его хешу в исходной записи, поэтому каждое значение теперь может совпасть с другим элементом или не совпасть ни с одним.", "few": "Не удалось переименовать {count} значения hash= из более старого сеанса в хеш элемента в его исходной записи: сохраненная диаграмма отображала кадрированную запись или обратный комплемент записи, и значения там указывают на элементы с несколькими исходными хешами, либо источники не были прочитаны повторно. Теперь hash= указывает на элемент по его хешу в исходной записи, поэтому каждое значение теперь может совпасть с другим элементом или не совпасть ни с одним.", "many": "Не удалось переименовать {count} значений hash= из более старого сеанса в хеш элемента в его исходной записи: сохраненная диаграмма отображала кадрированную запись или обратный комплемент записи, и значения там указывают на элементы с несколькими исходными хешами, либо источники не были прочитаны повторно. Теперь hash= указывает на элемент по его хешу в исходной записи, поэтому каждое значение теперь может совпасть с другим элементом или не совпасть ни с одним.", "other": "Не удалось переименовать {count} значения hash= из более старого сеанса в хеш элемента в его исходной записи: сохраненная диаграмма отображала кадрированную запись или обратный комплемент записи, и значения там указывают на элементы с несколькими исходными хешами, либо источники не были прочитаны повторно. Теперь hash= указывает на элемент по его хешу в исходной записи, поэтому каждое значение теперь может совпасть с другим элементом или не совпасть ни с одним."},
